// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Define colors
const colors = [
  '#ffd5b7', // pastel pink
  '#c9e9ff', // pastel blue
  '#d0f4de', // pastel green
  '#fff9b7', // pastel yellow
  '#e6c5ff', // pastel purple
  '#ffb3c6'  // pastel rose
];

// Draw circles with gradient effect
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 20
  );

  // Create gradient with two main colors
  gradient.addColorStop(0, colors[i]);
  gradient.addColorStop(1, colors[(i + 1) % 6]);

  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();

  // Add subtle border to each circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.stroke();
}

