// Draw spiral with cool tones
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Calculate new position for spiral arms
        const angle = depth * 0.5;
        const newX = x + Math.cos(angle) * r;
        const newY = y + Math.sin(angle) * r;

        // Draw spiral arm
        ctx.strokeStyle = `hsl(${20 + depth * 15}, 70%, ${70 - depth * 10}%)`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(newX, newY);
        ctx.stroke();

        // Recursive call for each arm
        drawSpiral(newX, newY, r * 0.95, depth - 1);
    }
}

