for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = 400 + Math.cos(angle) * 50;
    const y = 300 + Math.sin(angle) * 50;
    ctx.beginPath();
    ctx.arc(x, y, 15, 0, Math.PI * 2);
    ctx.fill();
}

// Draw tentacles - multiple pink strands
ctx.fillStyle = 'rgba(255, 192, 203, 0.7)';
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = 400 + Math.cos(angle) * 80;
    const y = 300 + Math.sin(angle) * 80;

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * 120, y + Math.sin(angle) * 120);

    // Create a gradient effect on tentacles
    const gradient = ctx.createLinearGradient(x, y, x + Math.cos(angle) * 120, y + Math.sin(angle) * 120);
    gradient.addColorStop(0, 'rgba(255, 192, 203, 0.7)');
    gradient.addColorStop(1, 'rgba(255, 165, 192, 0.3)');

    ctx.strokeStyle = gradient;
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.stroke();
}

