// Shell spiral
ctx.strokeStyle = '#8B4513';
ctx.lineWidth = 8;
ctx.beginPath();
let radius = 20;
for (let i = 0; i < 20; i++) {
    const angle = (i / 20) * Math.PI * 2;
    const x = 400 + Math.cos(angle) * radius;
    const y = 400 + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    radius += 8;
}
ctx.stroke();

